#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

# El asistente vive en scripts/, pero todo (.env, prisma, git) cuelga de la raíz.
cd "$(dirname "${BASH_SOURCE[0]}")/.." || { echo "no pude entrar al proyecto"; exit 1; }

TOTAL_STAGES=6

banner "Desplegar la app de noticias"

# ── 1. Supabase ───────────────────────────────────────────────────────────
stage "Supabase: crear la base de datos"
say "Creamos el Postgres donde se guardan las noticias."
warn "No registres tarjeta en ningún paso. El plan gratuito no la pide."
open_url "https://supabase.com/dashboard/projects"
step "Dale a 'New project'."
step "Nombre: el que quieras. Región: la más cercana (us-east-1 o us-west-1)."
step "Genera la contraseña de la base y GUÁRDALA: va dentro de las cadenas."
pause "Cuando el proyecto termine de aprovisionar (1-2 min), pulsa Enter."

say ""
say "Ahora las dos cadenas de conexión. Son distintas y hacen falta las dos."
step "Abre el botón 'Connect' de arriba (o Project Settings → Database)."
warn "Si la cadena trae [YOUR-PASSWORD], cámbialo por tu contraseña real antes de pegarla."

step "Busca 'Session pooler', puerto 5432. Con esa se CREA la tabla."
note "La de 6543 no puede crear tablas: por eso se necesitan las dos."
ask_secret DATABASE_URL "Pega la cadena Session pooler (5432):"
write_env DATABASE_URL "$DATABASE_URL"

step "Busca 'Transaction pooler', puerto 6543. Esa la usará Vercel."
ask_secret DATABASE_URL_POOLED "Pega la cadena Transaction pooler (6543):"
write_env DATABASE_URL_POOLED "$DATABASE_URL_POOLED"

# ── 2. Migración + ingesta real ───────────────────────────────────────────
stage "Crear la tabla y traer noticias de verdad"
say "Esta etapa la hago yo sola. No tienes que tocar nada."

step "Creando la tabla con Prisma..."
if npx prisma migrate dev --name init; then
  say ""
  say "Tabla creada."
else
  warn "La migración falló."
  note "Lo más común: la contraseña dentro de DATABASE_URL es incorrecta, o"
  note "pegaste la cadena de 6543 en lugar de la de 5432. Corrige .env y vuelve a correr."
  exit 1
fi

step "Trayendo noticias de las 15 fuentes..."
if npx tsx --env-file=.env scripts/sync.ts; then
  say ""
  say "La ingesta funcionó: arriba ves cuántas notas guardó cada fuente."
else
  warn "La ingesta falló. Manda el error de arriba y lo revisamos."
  exit 1
fi
pause "Pulsa Enter para seguir."

# ── 3. GitHub ─────────────────────────────────────────────────────────────
stage "GitHub: subir el código"
warn "El repo tiene que ser PÚBLICO: eso es lo que hace gratis el cron cada 15 min."
note "En repos privados GitHub Actions cobra por minutos y no alcanzaría."
open_url "https://github.com/new"
step "Nombre del repo: noticias"
step "Visibilidad: Public"
step "NO marques README, .gitignore ni licencia: el repo ya los trae."
pause "Cuando lo hayas creado, pulsa Enter."
ask REPO_URL "Pega la URL del repo (https://github.com/usuario/noticias):"

REPO_URL="${REPO_URL%.git}"
REPO_URL="${REPO_URL%/}"
write_env REPO_URL "$REPO_URL"

step "Guardando los archivos de migración que acaba de crear Prisma..."
git add -A
if git diff --cached --quiet; then
  note "No había nada nuevo que guardar."
else
  git commit -q -m "Agregar la migración inicial de la base de datos"
  say "Commit hecho."
fi

step "Conectando el repo y subiendo..."
if git remote get-url origin >/dev/null 2>&1; then
  git remote set-url origin "${REPO_URL}.git"
else
  git remote add origin "${REPO_URL}.git"
fi
if git push -u origin main; then
  say "Código subido."
else
  warn "El push falló. Suele ser que GitHub pidió credenciales en otra ventana,"
  note "o que el repo no está vacío. Revisa y vuelve a correr el asistente."
  exit 1
fi

# ── 4. Vercel ─────────────────────────────────────────────────────────────
stage "Vercel: publicar la app"

if [[ -z "$(_existing CRON_SECRET || true)" ]]; then
  step "Generando el secreto del cron..."
  write_env CRON_SECRET "$(openssl rand -hex 32)"
else
  CRON_SECRET="$(_existing CRON_SECRET)"
  note "Reutilizo el CRON_SECRET que ya estaba en .env."
fi

open_url "https://vercel.com/new"
step "Importa el repo 'noticias'. Detecta Next.js solo: no cambies el build."
step "Antes de dar Deploy, abre 'Environment Variables' y agrega estas dos:"
say ""
say "  DATABASE_URL"
say "  $DATABASE_URL_POOLED"
say ""
say "  CRON_SECRET"
say "  $CRON_SECRET"
say ""
warn "Ojo: en Vercel va la cadena de 6543, no la de 5432."
step "Ahora sí, dale Deploy y espera a que termine."
pause "Cuando el despliegue esté listo, pulsa Enter."
ask APP_URL "Pega la URL que te dio Vercel (https://....vercel.app):"
APP_URL="${APP_URL%/}"
write_env APP_URL "$APP_URL"

step "Comprobando que la app responde..."
codigo=$(curl -s -o /dev/null -w "%{http_code}" --max-time 30 "$APP_URL" || echo "000")
if [[ "$codigo" == "200" ]]; then
  say "La app responde correctamente (HTTP 200)."
else
  warn "La app respondió $codigo en lugar de 200."
  note "Mira los logs del despliegue en Vercel; lo más común es que falte"
  note "una variable de entorno o que esté mal copiada."
  if ! confirm "¿Sigo de todas formas?"; then exit 1; fi
fi

# ── 5. Cron ───────────────────────────────────────────────────────────────
stage "GitHub Actions: encender el cron"
say "Falta que GitHub pueda llamar a tu app cada 15 minutos."
note "No tienes la CLI de GitHub instalada, así que estos dos secretos van a mano."
open_url "${REPO_URL}/settings/secrets/actions"
step "Dale a 'New repository secret' y crea estos dos, uno por uno:"
say ""
say "  Nombre: APP_URL"
say "  Valor:  $APP_URL"
say ""
say "  Nombre: CRON_SECRET"
say "  Valor:  $CRON_SECRET"
say ""
warn "El CRON_SECRET debe ser idéntico al que pusiste en Vercel."
pause "Cuando hayas guardado los dos, pulsa Enter."

open_url "${REPO_URL}/actions"
step "Entra a 'Sincronizar noticias' → botón 'Run workflow' → Run workflow."
step "Espera a que el círculo se ponga verde (unos 30 segundos)."
pause "Cuando esté verde, pulsa Enter."

step "Comprobando que la app ya tiene noticias..."
if curl -s --max-time 30 "$APP_URL" | grep -q -iE "jornada|infobae|el país|npr|the hill|bbc|cnbc|marketwatch"; then
  say "Confirmado: la app está sirviendo noticias reales."
else
  warn "No encontré nombres de medios en la portada."
  note "Si el workflow salió verde, puede ser solo cuestión de recargar."
  note "Si salió rojo, abre la corrida en Actions y mándame lo que diga."
fi

# ── 6. iPhone ─────────────────────────────────────────────────────────────
stage "iPhone: instalarla en la pantalla de inicio"
say "Último paso, y este solo lo puedes hacer tú desde el teléfono."
say ""
step "Abre esta dirección en Safari (tiene que ser Safari, en Chrome no sale):"
say ""
say "  $APP_URL"
say ""
step "Toca el botón de compartir: el cuadrito con la flecha hacia arriba."
step "Baja y elige 'Añadir a pantalla de inicio'."
step "Dale 'Añadir'."
say ""
say "Queda con su propio icono, a pantalla completa y sin barra de Safari."
note "No caduca nunca: no hay que reinstalarla cada 7 días."
pause "Pulsa Enter para terminar."

finish
}

run_wizard "$@"; exit
